# Run from the package root after a rebuild, 46, 52b, 54b and the logs of the build were saved in data-raw/qa/out/:  Rscript data-raw/qa/61_fidelity_section.R
# Writes the section "What is and is not done to the source data" of data-raw/known_issues.md (between <!-- fidelity:start --> and <!-- fidelity:end -->): the final state, every operation applied to a source value or geometry,
# with the number of records or features it touches. Every number is computed here from the data in data/, the SPC file, the Census files and the saved results of the build scripts:
#   out/process_tracks.log, out/centroids.log (the logs of data-raw/process_tracks.R and add_centroids.R), data-raw/dat/fetch/exposure_summary*.rds (build_dat_exposure.R), out/63_land_report.rds (63), out/block_audit_<year>.rds (52b), out/path_accuracy.rds (46), out/ncei_comparison.rds (54b).
suppressMessages({library(sf); library(dplyr)}); sf_use_s2(FALSE); source("data-raw/qa/helpers.R"); for (f in list.files("data", pattern = "\\.rda$", full.names = TRUE)) load(f)
f0 <- function(x) formatC(x, format = "d", big.mark = ","); pc <- function(x, d = 1) sprintf(paste0("%.", d, "f%%"), 100 * x)
need <- function(f) { if (!file.exists(qa_out(f))) stop("Missing data-raw/qa/out/", f, ": run the script that writes it first.", call. = FALSE); readRDS(qa_out(f)) }
logn <- function(file, pattern) { l <- grep(pattern, readLines(qa_out(file)), value = TRUE)[1]; if (is.na(l)) stop("Pattern not found in ", file, ": ", pattern, call. = FALSE); as.numeric(sub(paste0(".*", pattern, "\\s*([0-9]+).*"), "\\1", l)) }
raw <- read.csv(qa_spc_csv(), stringsAsFactors = FALSE); tt <- st_drop_geometry(tornado_tracks); d <- tornado_exposure; n <- nrow(tt)
# ZCTA files as read: invalid polygons in EPSG:5070 (planar), what st_make_valid repairs
cache <- rappdirs::user_cache_dir("tigris"); zf <- c(`2000` = "tl_2010_us_zcta500", `2010` = "tl_2010_us_zcta510", `2020` = "tl_2020_us_zcta520")
zi <- vapply(zf, function(f) { z <- st_transform(st_read(file.path(cache, paste0(f, ".shp")), quiet = TRUE), 5070); c(features = nrow(z), invalid = sum(!st_is_valid(z))) }, c(features = 0, invalid = 0))
blk <- bind_rows(lapply(c(2000, 2010, 2020), function(v) need(sprintf("block_audit_%s.rds", v)))); bt <- blk %>% group_by(vintage) %>% summarise(blocks = sum(blocks), invalid = sum(invalid_blocks), multi = sum(blocks_in_more_than_one_zcta), extra = sum(extra_rows), dup_geoid = sum(duplicated_geoid_in_file), no_point = sum(no_internal_point), .groups = "drop")
DS <- readRDS("data-raw/dat/fetch/exposure_summary_tables.rds"); DP <- readRDS("data-raw/dat/fetch/exposure_summary.rds"); LR <- need("63_land_report.rds")
cl <- readLines(qa_out("centroids.log")); ii <- grep("geom_moved_to_surface", cl, fixed = TRUE)[1]; moved <- sum(as.numeric(sub(".*\\s", "", trimws(cl[(ii + 1):(ii + 3)])))); zero_res <- sum(zcta_centroids$centroid_type == "geometric")   # the report table of add_centroids.R wraps its last column
multi_pt <- logn("process_tracks.log", "Point tornadoes whose start lies in more than one ZCTA:")
dupid <- grepl("^[0-9]{4}_[0-9]+(-[0-9]+)?_[0-9]+$", tt$tornado_id); spc_w <- spc_records[spc_records$sg == 1, ]; pt <- tt$track_type == "point"; ln <- !pt; wz <- tt$wid_yd == 0 | is.na(tt$wid_yd)
reason <- ifelse(is.na(tt$elon) | is.na(tt$elat), "end missing", ifelse(tt$elon == 0 | tt$elat == 0, "end 0", ifelse(tt$elon == tt$slon & tt$elat == tt$slat, "end equal to the start", "")))
pa <- need("path_accuracy.rds"); nc <- need("ncei_comparison.rds")$R$agree_all
millions <- tt$loss_raw_unit == "millions"; dollars_exact <- tt$loss_raw * 1e6; ldiff <- max(abs(tt$property_loss_tornado_total - dollars_exact)[millions & tt$loss_raw > 0])
rat <- d$zcta_polygon_area_m2 / d$zcta_land_area_m2; sp <- d[d$spc_exposed, ]; touch_n <- sum(as.numeric(sub(".*: ([0-9]+)$", "\\1", grep("touch at a point only", readLines(qa_out("process_tracks.log")), value = TRUE))))
lost_zcta <- sum(pt & !tt$tornado_id %in% sp$tornado_id)
row <- function(op, touches, allowed) paste0("| ", op, " | ", touches, " | ", allowed, " |")
rows <- c(
 row("SPC records before 1996 are not used", paste0(f0(sum(raw$yr < 1996)), " of ", f0(nrow(raw)), " rows of the SPC file"), "Yes: the package starts in 1996 (inherited from the original package; no reason is documented)"),
 row("`spc_records`: every SPC column and every row from 1996 on, as SPC gives them (the time of day stays text); the column `tornado_id` is added", paste0(f0(nrow(spc_records)), " rows, ", ncol(spc_records) - 1, " SPC columns; `tornado_id` is `NA` for ", f0(sum(is.na(spc_records$tornado_id))), " segment rows whose year and `om` match no whole-track row or several"), "Yes: nothing is dropped; the added column is an identifier"),
 row("Identifiers shared by two tornadoes are renamed `_1`, `_2`", paste0(f0(sum(dupid)), " records (", paste(tt$tornado_id[dupid], collapse = ", "), ")"), "Yes: an identifier, not a source value; the raw `om` stays in `spc_records`"),
 row("Loss in millions of dollars (before 2007) is converted to dollars (`loss` times 1e6)", paste0(f0(sum(millions & tt$loss_raw > 0)), " nonzero values; the largest difference between the stored dollars and the exact product is ", format(ldiff, digits = 3), " dollars (the build stops if a value is not a whole number of dollars up to floating-point error)"), "Yes: an exact unit conversion; the raw value and unit are kept in `loss_raw` and `loss_raw_unit`"),
 row("A loss of 0 becomes `NA` in `property_loss_tornado_total`", paste0(f0(sum(is.na(tt$property_loss_tornado_total))), " tornadoes"), "Yes: NOAA says 0 does not mean $0; the raw value is kept in `loss_raw`"),
 row("A tornado with no usable end point (end coordinates missing, 0 or equal to the start) is a POINT at the start; SPC's raw coordinates, length and width are kept", paste0(f0(sum(pt)), " tornadoes (", pc(mean(pt)), "): ", paste(names(table(reason[pt])), f0(as.integer(table(reason[pt]))), collapse = ", ")), "Yes: no end point is invented; such a tornado exposes only the ZCTA that contains the start point"),
 row("A width of 0 or missing is never replaced; the width is not used to draw any shape", paste0(f0(sum(wz)), " tornadoes (", f0(sum(wz & ln)), " lines, ", f0(sum(wz & pt)), " points)"), "Nothing is changed"),
 row("The SPC line is the straight line (straight in EPSG:5070) from SPC's start to SPC's end point; a ZCTA is exposed when a positive length of the line lies in it, and the share of the line in each ZCTA is measured in EPSG:5070 (the length of the whole line is measured on the sphere)", paste0(f0(sum(ln)), " line tornadoes, ", f0(sum(d$spc_exposed & d$track_type == "line")), " SPC rows; ", f0(touch_n), " line-ZCTA pairs that touch at a point only (zero length) are not exposures"), "A line between two rounded points, not a damage path (section SPC exposure)"),
 row("Coordinates are projected to EPSG:5070 for areas, lengths and overlays, to a regional CRS for distances (EPSG:5070 in the 48 states, EPSG:3338 Alaska, ESRI:102007 Hawaii, EPSG:32161 Puerto Rico) and to EPSG:4269 for block points; maps are drawn in EPSG:4326", "every geometry that is measured or intersected", "Yes: projection"),
 row("ZCTA polygons repaired with `st_make_valid()` (counted in EPSG:5070 as read)", paste0("2000 file: ", zi[2, 1], " of ", f0(zi[1, 1]), "; 2010 file: ", zi[2, 2], " of ", f0(zi[1, 2]), "; 2020 file: ", zi[2, 3], " of ", f0(zi[1, 3])), "Yes: repairing invalid geometry"),
 row(paste0("Census block polygons repaired with `st_make_valid()` (counted over all blocks as read by the audit 52b; the DAT pipeline reads only the blocks of the tracts that the footprints reach and found ", f0(DS$blocks[["invalid_repaired"]]), " invalid)"), paste0("invalid blocks: 2000: ", f0(bt$invalid[bt$vintage == 2000]), " of ", f0(bt$blocks[bt$vintage == 2000]), "; 2010: ", f0(bt$invalid[bt$vintage == 2010]), " of ", f0(bt$blocks[bt$vintage == 2010]), "; 2020: ", f0(bt$invalid[bt$vintage == 2020]), " of ", f0(bt$blocks[bt$vintage == 2020])), "Yes: repairing invalid geometry"),
 row("Intersections of lines with ZCTAs: the pieces of one line in one ZCTA are merged (their lengths are added)", paste0(f0(nrow(sp)), " SPC rows (", f0(sum(sp$track_type == "line")), " from a line, ", f0(sum(sp$track_type == "point")), " from a start point; ", f0(multi_pt), " start points lie in more than one ZCTA)"), "Yes: merging"),
 row("A start point that lies in no ZCTA has no SPC row in `tornado_exposure`", paste0(f0(lost_zcta), " point tornadoes (they stay in `tornado_tracks`)"), "Yes: nothing is moved or invented"),
 row("Land-only shapes: the Census water polygons (AREAWATER) are subtracted from each ZCTA polygon and from each block polygon the footprints reach; areas and residents use the result, and the unit polygons and water polygons themselves are not changed", paste0("ZCTAs with a water polygon inside: 2000: ", f0(LR$zcta[["2000"]]$water_touched), " of ", f0(LR$zcta[["2000"]]$zctas), "; 2010: ", f0(LR$zcta[["2010"]]$water_touched), " of ", f0(LR$zcta[["2010"]]$zctas), "; 2020: ", f0(LR$zcta[["2020"]]$water_touched), " of ", f0(LR$zcta[["2020"]]$zctas), "; blocks with a water polygon inside: ", f0(sum(vapply(DP$passes, function(p) p$blocks_water_touched, 0))), " of ", f0(DS$blocks[["blocks_in_tracts"]]), " (blocks of the tracts the footprints reach); water polygons repaired: ", f0(LR$zcta[["2020"]]$water_invalid_repaired + LR$zcta[["2010"]]$water_invalid_repaired), "; the land-only ZCTA shape differs from `ALAND` by more than 1% for ", f0(LR$zcta[["2000"]]$over1), " (2000), ", f0(LR$zcta[["2010"]]$over1), " (2010) and ", f0(LR$zcta[["2020"]]$over1), " (2020) ZCTAs"), "Yes: subtracting Census water polygons from Census unit shapes; both areas and `ALAND` are shipped"),
 row("A block whose land-only shape is empty (area at most 0.001 square meters) but that has residents: the residents are allocated by the share of the block polygon that a footprint zone covers, and the block takes no part in the area shares", paste0(f0(DS$blocks[["blocks_no_land"]]), " of ", f0(DS$blocks[["blocks_in_tracts"]]), " blocks of the tracts reached have no land (", f0(DS$blocks[["no_land_but_aland_positive"]]), " with a Census land area above 0); ", f0(DS$blocks[["blocks_no_land_with_residents"]]), " hold residents (", f0(DS$blocks[["residents_in_no_land_blocks"]]), "), of which ", sprintf("%.1f", DS$blocks[["residents_by_polygon_share"]]), " are allocated to a footprint"), "Yes: a computed allocation rule, not a source value (section Land-only shapes)"),
 row("DAT footprints: the polygons rated EF0 to EF5 that a linked line touches are cut into zones by the highest rating (union and difference of polygons); a polygon that is invalid is repaired for this computation only", paste0(f0(DS$footprint[["polygons_used"]]), " polygons, ", f0(DS$footprint[["tornadoes_with_footprint"]]), " tornadoes, ", f0(DS$zones[["zones"]]), " zones; ", f0(DS$zones[["polygons_repaired"]]), " polygons repaired; polygons not used: ", f0(DS$polygons_other_total), " with another `efscale` and ", f0(DS$polygons_no_date), " with no date (they stay in `dat_polygons`)"), "Yes: merging polygons and repairing invalid geometry; the shipped polygons are not changed"),
 row("`zcta_centroids`: longitude and latitude are as computed (not rounded)", paste0(f0(nrow(zcta_centroids)), " rows"), "Nothing is rounded"),
 row("`zcta_centroids`: the geometric centroid of a ZCTA with no residents is replaced by a point on the polygon surface when it falls outside the polygon", paste0(f0(moved), " of ", f0(zero_res), " ZCTAs with no residents (sum over the three boundary years)"), "Yes: a computed centroid, not a source value; the type is `geometric`"),
 row("Population: a block with an `NA` population stops the build", paste0(f0(sum(is.na(zcta_centroids$zcta_pop))), " `NA` ZCTA populations; the 2020 block field `POP20` is `NA` for ", f0(sum(blk$pop_na_2020_field[blk$vintage == 2020], na.rm = TRUE)), " blocks"), "Nothing is replaced"),
 row("Population: a duplicated GEOID in a block file stops the build", paste0(f0(sum(bt$dup_geoid)), " duplicated GEOIDs in ", f0(sum(bt$blocks)), " blocks"), "Nothing is dropped"),
 row("Population: the share of the land of a block covered by a footprint zone, and every area share, is not capped; the build stops if it is above 1 by more than 1e-9", paste0(f0(DS$blocks[["pieces"]]), " zone-block pieces; the largest share is ", format(DS$blocks[["largest_share"]], digits = 12)), "Nothing is capped"),
 row("Population: a block whose internal point lies in more than one ZCTA keeps only its first ZCTA (`!duplicated(GEOID)`)", paste0(f0(sum(bt$multi)), " blocks (", f0(sum(bt$extra)), " rows dropped) in ", paste(bt$vintage, f0(bt$multi), sep = ": ", collapse = ", ")), "Not allowed under the fidelity rule without approval: reported to the maintainer"),
 row("DAT features: every feature of the three layers is kept, all fields, full resolution, in the service's spatial reference; no generalization, simplification, date filter, swath filter or field selection", paste0("points ", f0(nrow(dat_points)), ", lines ", f0(nrow(dat_lines)), ", polygons ", f0(nrow(dat_polygons)), " (equal to the counts the service reported); ", f0(sum(st_is_empty(dat_points))), " empty point, ", f0(sum(st_is_empty(dat_lines))), " empty line and ", f0(sum(st_is_empty(dat_polygons))), " empty polygon geometries and ", f0(sum(is.na(dat_points$stormdate))), " + ", f0(sum(is.na(dat_lines$stormdate))), " + ", f0(sum(is.na(dat_polygons$stormdate))), " features without a date are kept"), "Nothing is changed"),
 row("DAT dates: the text of milliseconds since 1970 is stored as a number (same value) and a `_utc` column is added", paste0(f0(sum(grepl("_utc$", c(names(dat_points), names(dat_lines), names(dat_polygons))))), " added columns"), "Yes: type conversion without loss; the raw values are kept"),
 row("DAT strings are as the service gives them (no character is removed)", paste0(f0(sum(grepl("\xc2\xad", c(dat_lines$event_id, dat_polygons$event_id, dat_points$event_id), fixed = TRUE, useBytes = TRUE))), " event ids contain a soft hyphen (U+00AD) and keep it"), "Nothing is changed"),
 row("`tornado_dat_link` and `dat_polygon_line_link` are computed on copies of the geometries projected to EPSG:5070; a polygon that is invalid is repaired for the computation only", paste0(f0(readRDS("data-raw/dat/fetch/build_summary.rds")$polygons_invalid), " polygons repaired; the shipped features are not repaired"), "Yes: projection and repairing invalid geometry"),
 row("Maps and boundary distances use the full TIGER/Line boundaries, not the generalized cartographic files", "every map and every `boundary_dist_km` call", "Nothing is generalized"))
pa <- need("path_accuracy.rds")
cls_txt <- paste(vapply(seq_len(nrow(pa$by_class)), function(i) paste0(pa$by_class$cls[i], " (", f0(pa$by_class$n[i]), " links): median ", sprintf("%.2f", pa$by_class$median[i]), " km, 90th percentile ", sprintf("%.2f", pa$by_class$p90[i]), " km"), ""), collapse = "; ")
acc <- paste0("**The SPC line is not a damage boundary at fine scales.** The SPC line is a straight line from SPC's start to SPC's end. It does not follow the curve of a real path, so it is not the path of the damage at scales finer than a kilometer: for the ", f0(pa$all[["n"]]), " SPC line tornadoes linked to a DAT line, the largest distance from a vertex of the DAT centerline to the SPC line has a median of ", sprintf("%.2f", pa$all[["median"]]), " km and a 90th percentile of ", sprintf("%.2f", pa$all[["p90"]]), " km, by length of the SPC line: ", cls_txt, ".")
basis <- paste0("**Area basis.** The DAT area shares divide by the area of the land-only shape of the unit (the unit polygon minus the Census water polygons), so numerator and denominator come from the same geometry and a share cannot exceed 1 except by floating-point error. The Census land area (`ALAND`) is shipped as `zcta_land_area_m2` and the polygon area as `zcta_polygon_area_m2`; the ZCTA polygons include inland and coastal water, so the polygon area is larger than the land area: it differs by more than 1% in ", f0(sum(abs(rat - 1) > .01)), " of ", f0(nrow(d)), " rows and by more than 10% in ", f0(sum(abs(rat - 1) > .1)), ".")
ncei <- paste0("**NCEI.** NCEI's Storm Events database is built from the same NWS Storm Data as SPC and is not independent of it. For ", f0(nc$n), " SPC tornadoes of 2007 to 2025 matched to NCEI events (within 2 km of the SPC line, within a day) the rating is equal for ", sprintf("%.2f", nc$rating_equal), " percent (`data-raw/qa/54b_ncei_comparison.R`).")
txt <- c("<!-- fidelity:start -->", "## What is and is not done to the source data", "",
 "The aim of the package is the highest quality of data on tornadoes, changed as little as possible. Allowed operations on source geometry are a coordinate transformation (projection), merging polygons and repairing invalid geometry, and each is listed below with the number of features it touches. No source geometry or coordinate is simplified, generalized, rounded, snapped, thinned or truncated, and no source value is capped, imputed or replaced: where a transformation is needed, the raw value is kept in its own column.", "",
 "| Operation | What it touches | Allowed |", "|---|---|---|", rows, "", acc, "", basis, "", ncei, "",
 "<!-- fidelity:end -->")
kl <- readLines("data-raw/known_issues.md"); a <- grep("<!-- fidelity:start -->", kl, fixed = TRUE); b <- grep("<!-- fidelity:end -->", kl, fixed = TRUE)
kl <- if (length(a) && length(b)) c(kl[seq_len(a - 1)], txt, kl[-seq_len(b)]) else append(kl, c(txt, ""), after = grep("^## Property loss", kl)[1] - 1)
writeLines(kl, "data-raw/known_issues.md"); cat(txt, sep = "\n")
